let W=480,H=270, state='title', last=0, elapsed=0, souls=0, level=1, xp=0, xpNeed=8, kills=0, shake=0, spawnClock=0, dashCooldown=0, invuln=0, attackClock=0, attackFx=0, toastClock=0, lastMob=0;
let player, enemies=[], gems=[], particles=[], trees=[], keys={}, joy={x:0,y:0}, pointer=null, upgrades=[], seed=24127;
const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
function resize(){const dpr=Math.min(devicePixelRatio||1,2),rect=canvas.getBoundingClientRect();W=Math.max(240,Math.round(rect.width*dpr/2));H=Math.max(135,Math.round(rect.height*dpr/2));canvas.width=W;canvas.height=H;ctx.imageSmoothingEnabled=false}
new ResizeObserver(resize).observe(canvas); resize();
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function reset(){elapsed=0;souls=0;level=1;xp=0;xpNeed=8;kills=0;shake=0;spawnClock=1.2;dashCooldown=0;invuln=1;attackClock=.35;attackFx=0;toastClock=0;lastMob=0;enemies=[];gems=[];particles=[];player={x:0,y:0,hp:100,maxHp:100,speed:45,damage:1,range:55,attackRate:.9,magnet:56,armor:0,dashPower:1,whip:0,regen:0};seed=24127;trees=[];for(let i=0;i<70;i++)trees.push({x:(rand()-.5)*1400,y:(rand()-.5)*850,kind:rand()>.46?0:1,scale:.7+rand()*.65});ui.level.textContent='01';ui.souls.textContent='000';ui.health.style.width='100%';ui.xp.style.width='0%';ui.weapon.innerHTML='ASHEN WHIP <span style="color:#545964">·</span> LV. 1';ui.run.textContent=String(1+Number(localStorage.getItem('nightfallRuns')||0)).padStart(2,'0')}
function startGame(){reset();state='playing';ui.overlay.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}
function showMessage(title,desc,button='Continue',choices=false){ui.modal.innerHTML=`<div class="eyebrow">${title}</div>${desc}${choices?'':`<button class="cta" id="modalAction">${button} →</button>`}`;if(!choices)document.getElementById('modalAction').onclick=()=>{ui.overlay.classList.add('hidden');state='playing';last=performance.now();requestAnimationFrame(loop)}}
const choicesPool=[
 {name:'Bloodbound',detail:'Recover 30% of your missing vitality.',icon:'♥',apply:()=>player.hp=Math.min(player.maxHp,player.hp+player.maxHp*.3)},
 {name:'Longer Reach',detail:'Your whip reaches 25% farther.',icon:'↗',apply:()=>player.range*=1.25},
 {name:'Quick Hands',detail:'Attack 20% faster.',icon:'✦',apply:()=>player.attackRate*=.8},
 {name:'Hollow Heart',detail:'Increase maximum vitality by 25.',icon:'♡',apply:()=>{player.maxHp+=25;player.hp=Math.min(player.maxHp,player.hp+25)}},
 {name:'Fleet Foot',detail:'Move 12% faster through the dark.',icon:'➤',apply:()=>player.speed*=1.12},
 {name:'Witchglass',detail:'Whip strikes deal 1 extra damage.',icon:'⌁',apply:()=>player.damage++},
 {name:'Soul Magnet',detail:'Gather souls from further away.',icon:'◉',apply:()=>player.magnet*=1.55},
 {name:'Second Wind',detail:'Restore 12 vitality and gain a little armor.',icon:'✚',apply:()=>{player.hp=Math.min(player.maxHp,player.hp+12);player.armor=Math.min(.35,player.armor+.06)}}
];
function levelUp(){level++;xp-=xpNeed;xpNeed=Math.ceil(xpNeed*1.35+2);state='level';const available=choicesPool.slice().sort(()=>rand()-.5).slice(0,3);ui.modal.innerHTML=`<div class="eyebrow">A SOUL REMEMBERED · LEVEL ${String(level).padStart(2,'0')}</div><h1 style="font-size:35px;margin:12px 0 4px">Choose a <em>blessing.</em></h1><p style="margin-bottom:10px">The forest yields its secrets.</p><div class="choices">${available.map((u,i)=>`<button class="choice" data-choice="${i}"><span class="ico">${u.icon}</span><span><b>${u.name}</b><small>${u.detail}</small></span></button>`).join('')}</div>`;available.forEach((u,i)=>ui.modal.querySelector(`[data-choice="${i}"]`).onclick=()=>{u.apply();ui.level.textContent=String(level).padStart(2,'0');ui.overlay.classList.add('hidden');state='playing';last=performance.now();toast('BLESSING RECEIVED');requestAnimationFrame(loop)});ui.overlay.classList.remove('hidden')}
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastClock=1.7}
function pause(){if(state==='playing'){state='paused';showMessage('THE FOREST HOLDS ITS BREATH',`<h1 style="font-size:36px">Take a <em>moment.</em></h1><p>Time only moves when you do.</p>`,'Resume')}else if(state==='paused'){state='playing';ui.overlay.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}}
ui.start.addEventListener('click',startGame);ui.pause.addEventListener('click',pause);document.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Space'].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if((e.key==='Escape'||e.key==='p')&&state==='playing')pause();if((e.key===' '||e.code==='Space')&&state==='playing')dash()});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
function dash(){if(state!=='playing'||dashCooldown>0)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y;let m=Math.hypot(dx,dy);if(m<.1){dx=1;dy=0;m=1}player.x+=dx/m*player.speed*.55*player.dashPower;player.y+=dy/m*player.speed*.55*player.dashPower;invuln=.48;dashCooldown=3.1;shake=2;for(let i=0;i<8;i++)particles.push({x:player.x,y:player.y,vx:(rand()-.5)*50,vy:(rand()-.5)*50,life:.25+rand()*.3,c:'#c8c0b1',size:2})}
ui.dash.addEventListener('pointerdown',e=>{e.preventDefault();dash()});
const stick=$('stick'),knob=$('knob');stick.addEventListener('pointerdown',e=>{stick.setPointerCapture(e.pointerId);pointer=e.pointerId;moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===pointer)moveStick(e)});function moveStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.hypot(dx,dy),max=34;if(m>max){dx*=max/m;dy*=max/m}joy.x=dx/max;joy.y=dy/max;knob.style.left=`calc(50% + ${dx}px)`;knob.style.top=`calc(50% + ${dy}px)`}function endStick(e){if(e.pointerId===pointer){pointer=null;joy.x=joy.y=0;knob.style.left='50%';knob.style.top='50%'}}stick.addEventListener('pointerup',endStick);stick.addEventListener('pointercancel',endStick);
function spawnEnemy(){const ang=rand()*Math.PI*2,dist=Math.max(W,H)*.65+20,x=player.x+Math.cos(ang)*dist,y=player.y+Math.sin(ang)*dist,t=elapsed;let type='ghoul';if(t>24&&rand()<.25)type='bat';if(t>55&&rand()<.22)type='brute';if(t>95&&rand()<.2)type='wraith';const cfg={ghoul:[2+Math.floor(t/48),13+Math.min(t*.035,4),13+Math.min(t*.025,5),1],bat:[1+Math.floor(t/70),25,9,1],brute:[5+Math.floor(t/55),8,22,2],wraith:[3+Math.floor(t/65),18,15,2]}[type];enemies.push({x,y,type,hp:cfg[0],maxHp:cfg[0],speed:cfg[1]+Math.min(t*.035,5),r:cfg[2],dmg:cfg[3],anim:rand()*8,hit:0})}
function addParticles(x,y,count,color){for(let i=0;i<count;i++){const a=rand()*6.28,s=12+rand()*55;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+rand()*.4,c:color,size:1+Math.floor(rand()*2)})}}
function nearest(){let best=null,bd=Infinity;for(const e of enemies){const d=Math.hypot(e.x-player.x,e.y-player.y);if(d<bd){bd=d;best=e}}return best}
function attack(){const target=nearest();if(!target)return;const dx=target.x-player.x,dy=target.y-player.y,d=Math.hypot(dx,dy);if(d>player.range+target.r)return;attackFx=.18;attackAngle=Math.atan2(dy,dx);const damage=player.damage;let hit=0;for(const e of enemies){const ex=e.x-player.x,ey=e.y-player.y,dist=Math.hypot(ex,ey),a=Math.atan2(ey,ex),diff=Math.atan2(Math.sin(a-attackAngle),Math.cos(a-attackAngle));if(dist<player.range+e.r&&Math.abs(diff)<.54){e.hp-=damage;e.hit=.12;hit++;addParticles(e.x,e.y,3,'#f8cb82')}}if(hit){shake=Math.min(3,shake+hit*.3);if(player.whip>0&&rand()<.22){player.hp=Math.min(player.maxHp,player.hp+1);}}}
let attackAngle=0;
function gainXP(value,x,y){gems.push({x,y,value,phase:rand()*6})}
function update(dt){elapsed+=dt;dashCooldown=Math.max(0,dashCooldown-dt);invuln=Math.max(0,invuln-dt);attackFx=Math.max(0,attackFx-dt);shake=Math.max(0,shake-dt*9);toastClock-=dt;if(toastClock<=0)ui.toast.classList.remove('show');if(player.regen>0)player.hp=Math.min(player.maxHp,player.hp+player.regen*dt);
let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y,mm=Math.hypot(mx,my);if(mm>1){mx/=mm;my/=mm}player.x+=mx*player.speed*dt;player.y+=my*player.speed*dt;
spawnClock-=dt;let interval=Math.max(.31,1.22-elapsed*.0045);if(spawnClock<=0){spawnEnemy();if(elapsed>80&&rand()<.2)spawnEnemy();spawnClock=interval}
attackClock-=dt;if(attackClock<=0){attack();attackClock=player.attackRate}
for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];e.anim+=dt*8;e.hit=Math.max(0,e.hit-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt;if(d<e.r+8&&invuln<=0){player.hp-=Math.max(.5,e.dmg-player.armor*5)*dt*7;invuln=.12;shake=Math.max(shake,1.3)}if(e.hp<=0){enemies.splice(i,1);kills++;souls++;gainXP(1,e.x,e.y);addParticles(e.x,e.y,8,e.type==='wraith'?'#9e7cec':'#d86168');if(rand()<.035)gems.push({x:e.x,y:e.y,value:4,heal:true,phase:0})}}
for(let i=gems.length-1;i>=0;i--){const g=gems[i],dx=player.x-g.x,dy=player.y-g.y,d=Math.hypot(dx,dy)||1;g.phase+=dt*4;if(d<player.magnet){const speed=95+(player.magnet-d)*3;g.x+=dx/d*speed*dt;g.y+=dy/d*speed*dt}if(d<10){if(g.heal)player.hp=Math.min(player.maxHp,player.hp+18);else{xp+=g.value;if(xp>=xpNeed){levelUp();break}}gems.splice(i,1)}}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.93;p.vy*=.93;p.life-=dt;if(p.life<=0)particles.splice(i,1)}
ui.clock.textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;ui.souls.textContent=String(souls).padStart(3,'0');ui.health.style.width=`${clamp(player.hp/player.maxHp*100,0,100)}%`;ui.xp.style.width=`${clamp(xp/xpNeed*100,0,100)}%`;ui.label.textContent=`VITALITY ${Math.ceil(player.hp)}/${player.maxHp}`;
if(player.hp<=0){endGame(false);return}if(elapsed>=180){endGame(true);return}}
function endGame(won){state='end';localStorage.setItem('nightfallRuns',String(Number(localStorage.getItem('nightfallRuns')||0)+1));const best=Math.max(elapsed,Number(localStorage.getItem('nightfallBest')||0));localStorage.setItem('nightfallBest',String(best));showMessage(won?'THE DAWN RETURNS':'THE LIGHT GOES OUT',`<h1 style="font-size:42px">${won?'You endured.':'The night has you.'}</h1><p>You survived <b style="color:#ffcf74">${Math.floor(elapsed/60)}:${String(Math.floor(elapsed%60)).padStart(2,'0')}</b> and gathered <b style="color:#ffcf74">${souls}</b> souls. Best: ${Math.floor(best/60)}:${String(Math.floor(best%60)).padStart(2,'0')} · ${kills} creatures banished.</p>`,'Play again')}

function draw(){const sx=shake?(rand()-.5)*shake:0,sy=shake?(rand()-.5)*shake:0;ctx.save();ctx.translate(sx,sy);ctx.fillStyle='#19252a';ctx.fillRect(-10,-10,W+20,H+20);const ox=W/2-player.x,oy=H/2-player.y;
// Mossy ground tiles
const tile=32,startX=Math.floor((player.x-W/2)/tile)*tile,startY=Math.floor((player.y-H/2)/tile)*tile;for(let y=startY;y<player.y+H/2+tile;y+=tile)for(let x=startX;x<player.x+W/2+tile;x+=tile){let gx=Math.floor(x/tile),gy=Math.floor(y/tile);let n=Math.abs((gx*73856093^gy*19349663)>>>0)%11;ctx.fillStyle=n<3?'#1a2929':n<7?'#1b2b2b':'#1c2c2b';ctx.fillRect(Math.floor(x+ox),Math.floor(y+oy),tile,tile);if(n===0){ctx.fillStyle='#314039';ctx.fillRect(x+ox+5,y+oy+7,2,2);ctx.fillRect(x+ox+19,y+oy+22,3,2)}if(n===4){ctx.fillStyle='#25352e';ctx.fillRect(x+ox+14,y+oy+11,2,3)}}
// Background forest silhouettes
for(const t of trees){let x=t.x+ox,y=t.y+oy;if(x<-35||x>W+35||y<-50||y>H+30)continue;const s=t.scale;ctx.fillStyle='#111f22';ctx.fillRect(Math.round(x-2*s),Math.round(y-17*s),Math.round(4*s),Math.round(19*s));ctx.fillStyle=t.kind?'#203331':'#233a34';ctx.fillRect(Math.round(x-10*s),Math.round(y-25*s),Math.round(20*s),Math.round(12*s));ctx.fillRect(Math.round(x-7*s),Math.round(y-31*s),Math.round(14*s),Math.round(7*s));ctx.fillStyle='#314538';ctx.fillRect(Math.round(x-5*s),Math.round(y-24*s),Math.round(3*s),Math.round(3*s));ctx.fillStyle='rgba(8,15,19,.25)';ctx.fillRect(Math.round(x-9*s),Math.round(y-4*s),Math.round(18*s),2)}
// Glowing pickups
for(const g of gems){let x=g.x+ox,y=g.y+oy,r=g.heal?4:2.5+Math.sin(g.phase)*.7;ctx.fillStyle=g.heal?'#75e0a1':'#f1cb75';ctx.globalAlpha=.22;ctx.fillRect(x-7,y-7,14,14);ctx.globalAlpha=1;ctx.fillStyle=g.heal?'#8cffb0':'#ffe19a';ctx.fillRect(Math.round(x-r),Math.round(y-r),Math.ceil(r*2),Math.ceil(r*2));ctx.fillStyle='#fff4c9';ctx.fillRect(Math.round(x-1),Math.round(y-1),2,2)}
// Enemies
for(const e of enemies){let x=Math.round(e.x+ox),y=Math.round(e.y+oy),bob=Math.round(Math.sin(e.anim)*1.5);if(x<-30||x>W+30||y<-30||y>H+30)continue;ctx.fillStyle='rgba(3,8,11,.38)';ctx.fillRect(x-7,y+6,14,3);if(e.type==='ghoul'){ctx.fillStyle=e.hit?'#fff0d0':'#7f4e62';ctx.fillRect(x-5,y-7+bob,10,12);ctx.fillStyle='#a66a69';ctx.fillRect(x-4,y-10+bob,8,5);ctx.fillStyle='#e2b875';ctx.fillRect(x-3,y-9+bob,2,2);ctx.fillRect(x+1,y-9+bob,2,2);ctx.fillStyle='#573d50';ctx.fillRect(x-7,y+1+bob,3,6);ctx.fillRect(x+4,y+1+bob,3,6)}else if(e.type==='bat'){ctx.fillStyle=e.hit?'#fff0d0':'#78549b';let flap=Math.round(Math.sin(e.anim*2)*3);ctx.fillRect(x-3,y-3,6,6);ctx.fillRect(x-9,y-4-flap,6,4);ctx.fillRect(x+3,y-4-flap,6,4);ctx.fillStyle='#df92b4';ctx.fillRect(x-1,y-1,2,2)}else if(e.type==='brute'){ctx.fillStyle=e.hit?'#fff0d0':'#855545';ctx.fillRect(x-9,y-9+bob,18,18);ctx.fillStyle='#bf795b';ctx.fillRect(x-7,y-12+bob,14,7);ctx.fillStyle='#f2b76b';ctx.fillRect(x-5,y-10+bob,3,2);ctx.fillRect(x+2,y-10+bob,3,2);ctx.fillStyle='#5e4140';ctx.fillRect(x-7,y+7+bob,5,4);ctx.fillRect(x+2,y+7+bob,5,4)}else{ctx.globalAlpha=.78;ctx.fillStyle=e.hit?'#fff0d0':'#6c70a5';ctx.fillRect(x-6,y-9+bob,12,17);ctx.fillStyle='#bab4eb';ctx.fillRect(x-4,y-12+bob,8,6);ctx.fillStyle='#f6d79a';ctx.fillRect(x-3,y-10+bob,2,2);ctx.fillRect(x+1,y-10+bob,2,2);ctx.globalAlpha=1}if(e.hp<e.maxHp){ctx.fillStyle='#15171e';ctx.fillRect(x-6,y-15,12,2);ctx.fillStyle='#d86267';ctx.fillRect(x-6,y-15,12*Math.max(0,e.hp/e.maxHp),2)}}
// Whip slash
if(attackFx>0){ctx.save();ctx.translate(W/2,H/2);ctx.rotate(attackAngle);ctx.globalAlpha=attackFx/.18;ctx.strokeStyle='#ffda91';ctx.lineWidth=2;ctx.beginPath();ctx.arc(4,0,player.range*.78,-.52,.52);ctx.stroke();ctx.fillStyle='#fff1bc';ctx.fillRect(Math.min(player.range*.78,W),-1,4,2);ctx.restore();ctx.globalAlpha=1}
// Player shadow + cape
let px=W/2,py=H/2;ctx.fillStyle='rgba(1,6,10,.5)';ctx.fillRect(px-7,py+7,14,4);if(invuln>0&&Math.floor(elapsed*18)%2===0)ctx.globalAlpha=.58;ctx.fillStyle='#853c50';ctx.fillRect(px-6,py-2,12,11);ctx.fillStyle='#a44c5a';ctx.fillRect(px-5,py-6,10,7);ctx.fillStyle='#e4c69a';ctx.fillRect(px-4,py-10,8,6);ctx.fillStyle='#f4ddad';ctx.fillRect(px-3,py-11,6,3);ctx.fillStyle='#302634';ctx.fillRect(px-5,py-7,10,2);ctx.fillStyle='#ffdf90';ctx.fillRect(px+1,py-5,2,2);ctx.fillStyle='#d9bd8b';ctx.fillRect(px+6,py-1,3,2);ctx.fillRect(px+8,py-2,2,4);ctx.globalAlpha=1;
// Vignette rendered CSS; dark peripheral fog subtle canvas atmospheric lighting
const grd=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.22,W/2,H/2,Math.max(W,H)*.7);grd.addColorStop(0,'rgba(9,13,22,0)');grd.addColorStop(1,'rgba(8,11,18,.24)');ctx.fillStyle=grd;ctx.fillRect(0,0,W,H);ctx.restore();
}
function loop(now){if(state!=='playing')return;let dt=Math.min(.045,(now-last)/1000||0);last=now;update(dt);draw();if(state==='playing')requestAnimationFrame(loop)}
// Pause and resume handling: modal action callback restores the clock and animation loop.
})();

