(()=>{'use strict';
const canvas=document.getElementById('screen'),ctx=canvas.getContext('2d',{alpha:false}),$=id=>document.getElementById(id);
const ui={overlay:$('overlay'),modal:$('modal'),start:$('start'),pause:$('pause'),level:$('level'),souls:$('souls'),clock:$('clock'),health:$('health'),xp:$('xp'),label:$('barlabel'),weapon:$('weaponLabel'),toast:$('toast'),dash:$('dash'),run:$('runNum')};
let W=480,H=270,state='title',last=0,elapsed=0,souls=0,level=1,xp=0,xpNeed=8,kills=0,shake=0,spawnClock=0,dashCooldown=0,invuln=0,attackClock=0,attackFx=0,toastClock=0,attackAngle=0;
let player,enemies=[],gems=[],particles=[],trees=[],keys={},joy={x:0,y:0},pointer=null,seed=24127;
const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296},clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function resize(){const dpr=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();W=Math.max(240,Math.round(r.width*dpr/2));H=Math.max(135,Math.round(r.height*dpr/2));canvas.width=W;canvas.height=H;ctx.imageSmoothingEnabled=false}new ResizeObserver(resize).observe(canvas);resize();
function reset(){elapsed=0;souls=0;level=1;xp=0;xpNeed=8;kills=0;shake=0;spawnClock=1.2;dashCooldown=0;invuln=1;attackClock=.35;attackFx=0;toastClock=0;enemies=[];gems=[];particles=[];player={x:0,y:0,hp:100,maxHp:100,speed:45,damage:1,range:55,attackRate:.9,magnet:56,armor:0,regen:0};seed=24127;trees=[];for(let i=0;i<70;i++)trees.push({x:(rand()-.5)*1400,y:(rand()-.5)*850,kind:rand()>.46?0:1,scale:.7+rand()*.65});ui.level.textContent='01';ui.souls.textContent='000';ui.health.style.width='100%';ui.xp.style.width='0%';ui.weapon.innerHTML='ASHEN WHIP <span style="color:#545964">·</span> LV. 1';ui.run.textContent=String(1+Number(localStorage.getItem('nightfallRuns')||0)).padStart(2,'0')}
function startGame(){reset();state='playing';ui.overlay.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}
function showMessage(title,desc,button='Continue'){ui.modal.innerHTML=`<div class="eyebrow">${title}</div>${desc}<button class="cta" id="modalAction">${button} →</button>`;document.getElementById('modalAction').onclick=()=>{ui.overlay.classList.add('hidden');state='playing';last=performance.now();requestAnimationFrame(loop)}}
const upgrades=[{name:'Bloodbound',detail:'Recover 30% of missing vitality.',icon:'♥',apply:()=>player.hp=Math.min(player.maxHp,player.hp+player.maxHp*.3)},{name:'Longer Reach',detail:'Your whip reaches 25% farther.',icon:'↗',apply:()=>player.range*=1.25},{name:'Quick Hands',detail:'Attack 20% faster.',icon:'✦',apply:()=>player.attackRate*=.8},{name:'Hollow Heart',detail:'Increase maximum vitality by 25.',icon:'♡',apply:()=>{player.maxHp+=25;player.hp=Math.min(player.maxHp,player.hp+25)}},{name:'Fleet Foot',detail:'Move 12% faster through the dark.',icon:'➤',apply:()=>player.speed*=1.12},{name:'Witchglass',detail:'Whip strikes deal 1 extra damage.',icon:'⌁',apply:()=>player.damage++},{name:'Soul Magnet',detail:'Gather souls from further away.',icon:'◉',apply:()=>player.magnet*=1.55},{name:'Second Wind',detail:'Restore 12 vitality and gain a little armor.',icon:'✚',apply:()=>{player.hp=Math.min(player.maxHp,player.hp+12);player.armor=Math.min(.35,player.armor+.06)}}];
function levelUp(){level++;xp-=xpNeed;xpNeed=Math.ceil(xpNeed*1.35+2);state='level';const available=upgrades.slice().sort(()=>rand()-.5).slice(0,3);ui.modal.innerHTML=`<div class="eyebrow">A SOUL REMEMBERED · LEVEL ${String(level).padStart(2,'0')}</div><h1 style="font-size:35px;margin:12px 0 4px">Choose a <em>blessing.</em></h1><p style="margin-bottom:10px">The forest yields its secrets.</p><div class="choices">${available.map((u,i)=>`<button class="choice" data-choice="${i}"><span class="ico">${u.icon}</span><span><b>${u.name}</b><small>${u.detail}</small></span></button>`).join('')}</div>`;available.forEach((u,i)=>ui.modal.querySelector(`[data-choice="${i}"]`).onclick=()=>{u.apply();ui.level.textContent=String(level).padStart(2,'0');ui.overlay.classList.add('hidden');state='playing';toast('BLESSING RECEIVED');last=performance.now();requestAnimationFrame(loop)});ui.overlay.classList.remove('hidden')}
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastClock=1.7}
