ui.start.addEventListener('click',startGame);ui.pause.addEventListener('click',pause);document.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Space'].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if((e.key==='Escape'||e.key==='p')&&state==='playing')pause();if((e.key===' '||e.code==='Space')&&state==='playing')dash()});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
function dash(){if(state!=='playing'||dashCooldown>0)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y,m=Math.hypot(dx,dy);if(m<.1){dx=1;dy=0;m=1}player.x+=dx/m*player.speed*.55;player.y+=dy/m*player.speed*.55;invuln=.48;dashCooldown=3.1;shake=2;for(let i=0;i<8;i++)particles.push({x:player.x,y:player.y,vx:(rand()-.5)*50,vy:(rand()-.5)*50,life:.25+rand()*.3,c:'#c8c0b1',size:2})}
ui.dash.addEventListener('pointerdown',e=>{e.preventDefault();dash()});const stick=$('stick'),knob=$('knob');stick.addEventListener('pointerdown',e=>{stick.setPointerCapture(e.pointerId);pointer=e.pointerId;moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===pointer)moveStick(e)});function moveStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.hypot(dx,dy),max=34;if(m>max){dx*=max/m;dy*=max/m}joy.x=dx/max;joy.y=dy/max;knob.style.left=`calc(50% + ${dx}px)`;knob.style.top=`calc(50% + ${dy}px)`}function endStick(e){if(e.pointerId===pointer){pointer=null;joy.x=joy.y=0;knob.style.left='50%';knob.style.top='50%'}}stick.addEventListener('pointerup',endStick);stick.addEventListener('pointercancel',endStick);
function spawnEnemy(){const ang=rand()*Math.PI*2,dist=Math.max(W,H)*.65+20,x=player.x+Math.cos(ang)*dist,y=player.y+Math.sin(ang)*dist,t=elapsed;let type='ghoul';if(t>24&&rand()<.25)type='bat';if(t>55&&rand()<.22)type='brute';if(t>95&&rand()<.2)type='wraith';const cfg={ghoul:[2+Math.floor(t/48),13+Math.min(t*.035,4),13+Math.min(t*.025,5),1],bat:[1+Math.floor(t/70),25,9,1],brute:[5+Math.floor(t/55),8,22,2],wraith:[3+Math.floor(t/65),18,15,2]}[type];enemies.push({x,y,type,hp:cfg[0],maxHp:cfg[0],speed:cfg[1]+Math.min(t*.035,5),r:cfg[2],dmg:cfg[3],anim:rand()*8,hit:0})}
function addParticles(x,y,count,color){for(let i=0;i<count;i++){const a=rand()*6.28,s=12+rand()*55;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+rand()*.4,c:color,size:1+Math.floor(rand()*2)})}}
function nearest(){let best=null,bd=Infinity;for(const e of enemies){const d=Math.hypot(e.x-player.x,e.y-player.y);if(d<bd){bd=d;best=e}}return best}
function attack(){const target=nearest();if(!target)return;const dx=target.x-player.x,dy=target.y-player.y,d=Math.hypot(dx,dy);if(d>player.range+target.r)return;attackFx=.18;attackAngle=Math.atan2(dy,dx);let hit=0;for(const e of enemies){const ex=e.x-player.x,ey=e.y-player.y,dist=Math.hypot(ex,ey),a=Math.atan2(ey,ex),diff=Math.atan2(Math.sin(a-attackAngle),Math.cos(a-attackAngle));if(dist<player.range+e.r&&Math.abs(diff)<.54){e.hp-=player.damage;e.hit=.12;hit++;addParticles(e.x,e.y,3,'#f8cb82')}}if(hit){shake=Math.min(3,shake+hit*.3);if(player.whip>0&&rand()<.22)player.hp=Math.min(player.maxHp,player.hp+1)}}
