function update(dt){elapsed+=dt;dashCooldown=Math.max(0,dashCooldown-dt);invuln=Math.max(0,invuln-dt);attackFx=Math.max(0,attackFx-dt);shake=Math.max(0,shake-dt*9);toastClock-=dt;if(toastClock<=0)ui.toast.classList.remove('show');if(player.regen>0)player.hp=Math.min(player.maxHp,player.hp+player.regen*dt);let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y,mm=Math.hypot(mx,my);if(mm>1){mx/=mm;my/=mm}player.x+=mx*player.speed*dt;player.y+=my*player.speed*dt;spawnClock-=dt;if(spawnClock<=0){spawnEnemy();if(elapsed>80&&rand()<.2)spawnEnemy();spawnClock=Math.max(.31,1.22-elapsed*.0045)}attackClock-=dt;if(attackClock<=0){attack();attackClock=player.attackRate}
for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];e.anim+=dt*8;e.hit=Math.max(0,e.hit-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt;if(d<e.r+8&&invuln<=0){player.hp-=Math.max(.5,e.dmg-player.armor*5)*dt*7;invuln=.12;shake=Math.max(shake,1.3)}if(e.hp<=0){enemies.splice(i,1);kills++;souls++;gainXP(1,e.x,e.y);addParticles(e.x,e.y,8,e.type==='wraith'?'#9e7cec':'#d86168');if(rand()<.035)gems.push({x:e.x,y:e.y,value:4,heal:true,phase:0})}}
for(let i=gems.length-1;i>=0;i--){const g=gems[i],dx=player.x-g.x,dy=player.y-g.y,d=Math.hypot(dx,dy)||1;g.phase+=dt*4;if(d<player.magnet){const speed=95+(player.magnet-d)*3;g.x+=dx/d*speed*dt;g.y+=dy/d*speed*dt}if(d<10){if(g.heal)player.hp=Math.min(player.maxHp,player.hp+18);else{xp+=g.value;if(xp>=xpNeed){levelUp();break}}gems.splice(i,1)}}
for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.93;p.vy*=.93;p.life-=dt;if(p.life<=0)particles.splice(i,1)}ui.clock.textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;ui.souls.textContent=String(souls).padStart(3,'0');ui.health.style.width=`${clamp(player.hp/player.maxHp*100,0,100)}%`;ui.xp.style.width=`${clamp(xp/xpNeed*100,0,100)}%`;ui.label.textContent=`VITALITY ${Math.ceil(player.hp)}/${player.maxHp}`;if(player.hp<=0){endGame(false);return}if(elapsed>=180)endGame(true)}
function endGame(won){state='end';localStorage.setItem('nightfallRuns',String(Number(localStorage.getItem('nightfallRuns')||0)+1));const best=Math.max(elapsed,Number(localStorage.getItem('nightfallBest')||0));localStorage.setItem('nightfallBest',String(best));showMessage(won?'THE DAWN RETURNS':'THE LIGHT GOES OUT',`<h1 style="font-size:42px">${won?'You endured.':'The night has you.'}</h1><p>You survived <b style="color:#ffcf74">${Math.floor(elapsed/60)}:${String(Math.floor(elapsed%60)).padStart(2,'0')}</b> and gathered <b style="color:#ffcf74">${souls}</b> souls. Best: ${Math.floor(best/60)}:${String(Math.floor(best%60)).padStart(2,'0')} · ${kills} creatures banished.</p>`,'Play again');document.getElementById('modalAction').onclick=startGame}

function draw(){const sx=shake?(rand()-.5)*shake:0,sy=shake?(rand()-.5)*shake:0;ctx.save();ctx.translate(sx,sy);ctx.fillStyle='#19252a';ctx.fillRect(-10,-10,W+20,H+20);const ox=W/2-player.x,oy=H/2-player.y,tile=32,startX=Math.floor((player.x-W/2)/tile)*tile,startY=Math.floor((player.y-H/2)/tile)*tile;for(let y=startY;y<player.y+H/2+tile;y+=tile)for(let x=startX;x<player.x+W/2+tile;x+=tile){let gx=Math.floor(x/tile),gy=Math.floor(y/tile),n=Math.abs((gx*73856093^gy*19349663)>>>0)%11;ctx.fillStyle=n<3?'#1a2929':n<7?'#1b2b2b':'#1c2c2b';ctx.fillRect(Math.floor(x+ox),Math.floor(y+oy),tile,tile);if(n===0){ctx.fillStyle='#314039';ctx.fillRect(x+ox+5,y+oy+7,2,2);ctx.fillRect(x+ox+19,y+oy+22,3,2)}if(n===4){ctx.fillStyle='#25352e';ctx.fillRect(x+ox+14,y+oy+11,2,3)}}
