function attack(){let target=null,best=Infinity;for(const e of foes){let d=Math.hypot(e.x-hero.x,e.y-hero.y);if(d<best){best=d;target=e}}if(!target||best>hero.range+target.r)return;attackFx=.18;attackAngle=Math.atan2(target.y-hero.y,target.x-hero.x);let hit=0;for(const e of foes){let dx=e.x-hero.x,dy=e.y-hero.y,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx),diff=Math.atan2(Math.sin(a-attackAngle),Math.cos(a-attackAngle));if(d<hero.range+e.r&&Math.abs(diff)<.54){e.hp-=hero.damage;e.hit=.12;hit++;burst(e.x,e.y,3,'#f8cb82')}}if(hit)shake=Math.min(3,shake+hit*.3)}
