function update(dt){time+=dt;dashWait=Math.max(0,dashWait-dt);invuln=Math.max(0,invuln-dt);attackFx=Math.max(0,attackFx-dt);shake=Math.max(0,shake-dt*9);toastWait-=dt;if(toastWait<=0)ui.toast.classList.remove('show');let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+stick.x,y=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+stick.y,m=Math.hypot(x,y);if(m>1){x/=m;y/=m}hero.x+=x*hero.speed*dt;hero.y+=y*hero.speed*dt;spawn-=dt;if(spawn<=0){spawnEnemy();if(time>80&&rand()<.2)spawnEnemy();spawn=Math.max(.31,1.18-time*.004)}attackClock-=dt;if(attackClock<=0){attack();attackClock=hero.rate}
for(let i=foes.length-1;i>=0;i--){let e=foes[i],dx=hero.x-e.x,dy=hero.y-e.y,d=Math.hypot(dx,dy)||1;e.anim+=dt*8;e.hit=Math.max(0,e.hit-dt);e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt;if(d<e.r+8&&invuln<=0){hero.hp-=Math.max(.5,1-hero.armor*5)*dt*7;invuln=.12;shake=Math.max(shake,1.3)}if(e.hp<=0){foes.splice(i,1);kills++;souls++;orbs.push({x:e.x,y:e.y,value:1,phase:rand()*6});burst(e.x,e.y,7,e.type==='wraith'?'#9e7cec':'#d86168');if(rand()<.035)orbs.push({x:e.x,y:e.y,value:0,heal:true,phase:0})}}
for(let i=orbs.length-1;i>=0;i--){let o=orbs[i],dx=hero.x-o.x,dy=hero.y-o.y,d=Math.hypot(dx,dy)||1;o.phase+=dt*4;if(d<hero.magnet){let s=95+(hero.magnet-d)*3;o.x+=dx/d*s*dt;o.y+=dy/d*s*dt}if(d<10){if(o.heal)hero.hp=Math.min(hero.max,hero.hp+18);else{xp+=o.value;if(xp>=need){levelUp();break}}orbs.splice(i,1)}}for(let i=bits.length-1;i>=0;i--){let b=bits[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.vx*=.93;b.vy*=.93;b.life-=dt;if(b.life<=0)bits.splice(i,1)}
ui.clock.textContent=`${String(Math.floor(time/60)).padStart(2,'0')}:${String(Math.floor(time%60)).padStart(2,'0')}`;ui.souls.textContent=String(souls).padStart(3,'0');ui.health.style.width=`${clamp(hero.hp/hero.max*100,0,100)}%`;ui.xp.style.width=`${clamp(xp/need*100,0,100)}%`;ui.label.textContent=`VITALITY ${Math.ceil(hero.hp)}/${hero.max}`;if(hero.hp<=0)end(false);else if(time>=180)end(true)}
function draw(){const ox=W/2-hero.x,oy=H/2-hero.y;ctx.save();ctx.translate((rand()-.5)*shake,(rand()-.5)*shake);ctx.fillStyle='#19252a';ctx.fillRect(-10,-10,W+20,H+20);const tile=32,sx=Math.floor((hero.x-W/2)/tile)*tile,sy=Math.floor((hero.y-H/2)/tile)*tile;for(let y=sy;y<hero.y+H/2+tile;y+=tile)for(let x=sx;x<hero.x+W/2+tile;x+=tile){let n=Math.abs((Math.floor(x/tile)*73856093^Math.floor(y/tile)*19349663)>>>0)%11;ctx.fillStyle=n<3?'#1a2929':n<7?'#1b2b2b':'#1c2c2b';ctx.fillRect(Math.floor(x+ox),Math.floor(y+oy),tile,tile);if(n===0){ctx.fillStyle='#314039';ctx.fillRect(x+ox+6,y+oy+8,2,2)}}for(const t of trees){let x=t.x+ox,y=t.y+oy,s=t.size;if(x<-35||x>W+35||y<-45||y>H+30)continue;ctx.fillStyle='#111f22';ctx.fillRect(x-2*s,y-15*s,4*s,18*s);ctx.fillStyle=t.kind?'#203331':'#233a34';ctx.fillRect(x-10*s,y-24*s,20*s,13*s);ctx.fillRect(x-7*s,y-30*s,14*s,8*s);ctx.fillStyle='#314538';ctx.fillRect(x-5*s,y-23*s,3*s,3*s)}for(const o of orbs){let x=o.x+ox,y=o.y+oy;ctx.globalAlpha=.25;ctx.fillStyle=o.heal?'#75e0a1':'#f1cb75';ctx.fillRect(x-6,y-6,12,12);ctx.globalAlpha=1;ctx.fillStyle=o.heal?'#8cffb0':'#ffe19a';ctx.fillRect(x-2,y-2,4,4)}for(const e of foes){let x=Math.round(e.x+ox),y=Math.round(e.y+oy),b=Math.round(Math.sin(e.anim)*1.5);if(x<-30||x>W+30||y<-30||y>H+30)continue;ctx.fillStyle='rgba(3,8,11,.4)';ctx.fillRect(x-7,y+6,14,3);ctx.fillStyle=e.hit?'#fff0d0':({ghoul:'#855363',bat:'#79549b',brute:'#965b4b',wraith:'#7175aa'}[e.type]);if(e.type==='bat'){let flap=Math.round(Math.sin(e.anim*2)*3);ctx.fillRect(x-9,y-4-flap,18,8);ctx.fillRect(x-3,y-3,6,6)}else{let size=e.type==='brute'?18:12;ctx.fillRect(x-size/2,y-size/2+b,size,size);ctx.fillStyle=e.type==='wraith'?'#d8c6ff':'#e2b875';ctx.fillRect(x-3,y-3+b,2,2);ctx.fillRect(x+1,y-3+b,2,2)}if(e.hp<e.max){ctx.fillStyle='#15171e';ctx.fillRect(x-6,y-14,12,2);ctx.fillStyle='#d86267';ctx.fillRect(x-6,y-14,12*Math.max(0,e.hp/e.max),2)}}for(const p of bits){ctx.globalAlpha=clamp(p.life*3,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x+ox,p.y+oy,p.size,p.size)}ctx.globalAlpha=1;if(attackFx>0){ctx.save();ctx.translate(W/2,H/2);ctx.rotate(attackAngle);ctx.globalAlpha=attackFx/.18;ctx.strokeStyle='#ffda91';ctx.lineWidth=2;ctx.beginPath();ctx.arc(4,0,hero.range*.78,-.52,.52);ctx.stroke();ctx.restore();ctx.globalAlpha=1}let px=W/2,py=H/2;ctx.fillStyle='rgba(1,6,10,.5)';ctx.fillRect(px-7,py+7,14,4);if(invuln>0&&Math.floor(time*18)%2===0)ctx.globalAlpha=.55;ctx.fillStyle='#853c50';ctx.fillRect(px-6,py-2,12,11);ctx.fillStyle='#a44c5a';ctx.fillRect(px-5,py-6,10,7);ctx.fillStyle='#e4c69a';ctx.fillRect(px-4,py-10,8,6);ctx.fillStyle='#302634';ctx.fillRect(px-5,py-7,10,2);ctx.fillStyle='#ffdf90';ctx.fillRect(px+1,py-5,2,2);ctx.globalAlpha=1;let g=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.22,W/2,H/2,Math.max(W,H)*.7);g.addColorStop(0,'rgba(9,13,22,0)');g.addColorStop(1,'rgba(8,11,18,.24)');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.restore()}
function frame(now){if(state!=='playing')return;const dt=Math.min(.045,(now-last)/1000||0);last=now;update(dt);draw();if(state==='playing')requestAnimationFrame(frame)}
})();

